data.config.yaml:
{
  "extensions": {
    "health_check": {
      "endpoint": "127.0.0.1:13133"
    },
    "basicauth/ingest": {
      "client_auth": {
        "username": "ingest",
        "password_file": "/run/telemetry-auth/ingest-password"
      }
    }
  },
  "receivers": {
    "otlp/agent": {
      "protocols": {
        "http": {
          "endpoint": "127.0.0.1:4320",
          "max_request_body_size": 1048576
        }
      }
    },
    "otlp": {
      "protocols": {
        "http": {
          "endpoint": "0.0.0.0:4318",
          "max_request_body_size": 1048576
        }
      }
    },
    "k8s_cluster": {
      "auth_type": "serviceAccount",
      "collection_interval": "15s",
      "node_conditions_to_report": [
        "Ready",
        "MemoryPressure",
        "DiskPressure"
      ],
      "allocatable_types_to_report": [
        "cpu",
        "memory"
      ],
      "metrics": {
        "k8s.container.status.reason": {
          "enabled": true
        }
      }
    },
    "kubelet_stats": {
      "collection_interval": "15s",
      "auth_type": "serviceAccount",
      "endpoint": "https://${env:K8S_NODE_NAME}:10250",
      "ca_file": "/etc/aegis/kubelet-ca.pem",
      "insecure_skip_verify": false,
      "metric_groups": [
        "node",
        "pod",
        "container"
      ]
    }
  },
  "processors": {
    "memory_limiter": {
      "check_interval": "1s",
      "limit_mib": 256,
      "spike_limit_mib": 64
    },
    "transform/identity": {
      "trace_statements": [
        {
          "context": "span",
          "statements": [
            "delete_matching_keys(resource.attributes, \"^k8s\\\\.\")",
            "delete_key(resource.attributes, \"aegis.cluster.uid\")"
          ]
        }
      ],
      "metric_statements": [
        {
          "context": "datapoint",
          "statements": [
            "delete_matching_keys(resource.attributes, \"^k8s\\\\.\")",
            "delete_key(resource.attributes, \"aegis.cluster.uid\")"
          ]
        }
      ],
      "log_statements": [
        {
          "context": "log",
          "statements": [
            "delete_matching_keys(resource.attributes, \"^k8s\\\\.\")",
            "delete_key(resource.attributes, \"aegis.cluster.uid\")"
          ]
        }
      ]
    },
    "k8s_attributes": {
      "auth_type": "serviceAccount",
      "passthrough": false,
      "filter": {
        "node_from_env_var": "K8S_NODE_NAME"
      },
      "extract": {
        "metadata": [
          "k8s.namespace.name",
          "k8s.pod.name",
          "k8s.pod.uid",
          "k8s.node.name"
        ]
      },
      "pod_association": [
        {
          "sources": [
            {
              "from": "connection"
            }
          ]
        }
      ]
    },
    "filter/unknown": {
      "error_mode": "ignore",
      "traces": {
        "span": [
          "resource.attributes[\"k8s.namespace.name\"] == nil",
          "not IsMatch(resource.attributes[\"k8s.namespace.name\"], \"^aegis-\")"
        ]
      },
      "metrics": {
        "datapoint": [
          "resource.attributes[\"k8s.namespace.name\"] == nil",
          "not IsMatch(resource.attributes[\"k8s.namespace.name\"], \"^aegis-\")"
        ]
      },
      "logs": {
        "log_record": [
          "resource.attributes[\"k8s.namespace.name\"] == nil",
          "not IsMatch(resource.attributes[\"k8s.namespace.name\"], \"^aegis-\")"
        ]
      }
    },
    "resource/cluster": {
      "attributes": [
        {
          "key": "aegis.cluster.uid",
          "value": "668172eb-130b-4b59-8629-7448aaa382e9",
          "action": "upsert"
        }
      ]
    },
    "batch": {
      "timeout": "5s",
      "send_batch_size": 256,
      "send_batch_max_size": 512
    }
  },
  "exporters": {
    "prometheus": {
      "endpoint": "127.0.0.1:8889",
      "resource_to_telemetry_conversion": {
        "enabled": true
      },
      "metric_expiration": "90s",
      "send_timestamps": true
    },
    "otlp_http/loki": {
      "endpoint": "http://loki.aegis-observability.svc.cluster.local:8081/otlp",
      "auth": {
        "authenticator": "basicauth/ingest"
      },
      "timeout": "5s"
    },
    "otlp_http/tempo": {
      "endpoint": "http://tempo.aegis-observability.svc.cluster.local:8081",
      "auth": {
        "authenticator": "basicauth/ingest"
      },
      "timeout": "5s"
    }
  },
  "service": {
    "extensions": [
      "health_check",
      "basicauth/ingest"
    ],
    "telemetry": {
      "logs": {
        "level": "warn"
      },
      "metrics": {
        "level": "basic",
        "readers": [
          {
            "pull": {
              "exporter": {
                "prometheus": {
                  "host": "127.0.0.1",
                  "port": 8888
                }
              }
            }
          }
        ]
      }
    },
    "pipelines": {
      "metrics/apps": {
        "receivers": [
          "otlp"
        ],
        "processors": [
          "memory_limiter",
          "transform/identity",
          "k8s_attributes",
          "filter/unknown",
          "resource/cluster",
          "batch"
        ],
        "exporters": [
          "prometheus"
        ]
      },
      "metrics/cluster": {
        "receivers": [
          "k8s_cluster",
          "kubelet_stats"
        ],
        "processors": [
          "memory_limiter",
          "resource/cluster",
          "batch"
        ],
        "exporters": [
          "prometheus"
        ]
      },
      "logs/containers": {
        "receivers": [
          "otlp/agent"
        ],
        "processors": [
          "memory_limiter",
          "filter/unknown",
          "resource/cluster",
          "batch"
        ],
        "exporters": [
          "otlp_http/loki"
        ]
      },
      "logs": {
        "receivers": [
          "otlp"
        ],
        "processors": [
          "memory_limiter",
          "transform/identity",
          "k8s_attributes",
          "filter/unknown",
          "resource/cluster",
          "batch"
        ],
        "exporters": [
          "otlp_http/loki"
        ]
      },
      "traces": {
        "receivers": [
          "otlp"
        ],
        "processors": [
          "memory_limiter",
          "transform/identity",
          "k8s_attributes",
          "filter/unknown",
          "resource/cluster",
          "batch"
        ],
        "exporters": [
          "otlp_http/tempo"
        ]
      }
    }
  }
}

data.nginx.conf:
pid /tmp/nginx.pid;
error_log /dev/stderr warn;
worker_processes 1;
events { worker_connections 128; }
http {
 access_log off;
 client_max_body_size 2m;
 client_body_temp_path /tmp/client_temp;
 proxy_temp_path /tmp/proxy_temp;
 fastcgi_temp_path /tmp/fastcgi_temp;
 uwsgi_temp_path /tmp/uwsgi_temp;
 scgi_temp_path /tmp/scgi_temp;
 proxy_connect_timeout 3s;
 proxy_read_timeout 10s;
 server {
  listen 8080;
  location = /ready { proxy_pass http://127.0.0.1:13133/; }
  location ~ ^(/metrics|/metrics)$ {
   if ($request_method != GET) { return 405; }
   auth_basic "Aegis telemetry";
   auth_basic_user_file /run/telemetry-auth/query.htpasswd;
   proxy_pass http://127.0.0.1:8889;
  }
  location = /internal-metrics {
   auth_basic "Aegis telemetry";
   auth_basic_user_file /run/telemetry-auth/query.htpasswd;
   proxy_pass http://127.0.0.1:8888/metrics;
  }
  location / { return 404; }
 }
 server {
  listen 8081;
  location = /v1/logs {
   if ($request_method != POST) { return 405; }
   auth_basic "Aegis ingest";
   auth_basic_user_file /run/telemetry-auth/agent.htpasswd;
   proxy_pass http://127.0.0.1:4320;
  }
  location / { return 404; }
 }
}
